"""
simulate_ml_model.py
--------------------
Simulates an ML Risk Prediction pipeline and automatically links
predicted risks to contract clauses using the ContractPulse AI Evidence API.

Run this script to test the ML Connection functionality:
    python simulate_ml_model.py
"""

import requests
import json
import sys

API_BASE_URL = "http://localhost:8000"

# Simulated ML Risk predictions generated by ContractPulse risk models
MOCK_PREDICTIONS = [
    {
        "project_id": "CP-2048",
        "risk_type": "Schedule slippage",
        "factor_title": "Permit approval lag",
        "risk_description": "Environmental review is 23 days behind baseline. NYS DEC Article 15 permit issuance delayed.",
        "risk_score": 78.0
    },
    {
        "project_id": "CP-2048",
        "risk_type": "Subcontractor capacity deficit",
        "factor_title": "Marine piling crew shortage",
        "risk_description": "Two specialist piling crews operating below minimum staffing quota for 6 consecutive days.",
        "risk_score": 64.0
    },
    {
        "project_id": "CP-1932",
        "risk_type": "Material cost variance",
        "factor_title": "Acoustic panel price surge",
        "risk_description": "Steel and precast acoustic panel prices deviated 12% over bid baseline index.",
        "risk_score": 56.0
    },
    {
        "project_id": "CP-1764",
        "risk_type": "Budget burn ahead of plan",
        "factor_title": "Hydrostatic testing overtime",
        "risk_description": "Monthly requisition reached 124% of projected progress milestone during water main testing.",
        "risk_score": 47.0
    }
]

def check_backend_health():
    try:
        res = requests.get(f"{API_BASE_URL}/api/health", timeout=3)
        if res.status_code == 200:
            print("[+] Backend is online and healthy.\n")
            return True
    except Exception:
        pass
    print("[-] Warning: Backend is not reachable at http://localhost:8000.")
    print("    Please ensure uvicorn is running: uvicorn main:app --reload\n")
    return False

def run_ml_pipeline():
    print("=" * 70)
    print(" CONTRACTPULSE AI: ML RISK -> CONTRACT EVIDENCE LINKING PIPELINE")
    print("=" * 70)

    if not check_backend_health():
        sys.exit(1)

    for i, pred in enumerate(MOCK_PREDICTIONS, 1):
        print(f"\n--- [Prediction #{i}] ---")
        print(f"Project ID   : {pred['project_id']}")
        print(f"Risk Type    : {pred['risk_type']} ({pred['risk_score']}% probability)")
        print(f"Risk Factor  : {pred['factor_title']}")
        print(f"Description  : {pred['risk_description']}")
        print("\n--> Querying pgvector RAG for relevant contract evidence...")

        try:
            resp = requests.post(
                f"{API_BASE_URL}/api/ml/connect-evidence",
                json=pred,
                headers={"Content-Type": "application/json"},
                timeout=10
            )
            if resp.status_code == 200:
                evidence_items = resp.json()
                print(f"[+] Retrieved {len(evidence_items)} contractual evidence citations:")
                for idx, ev in enumerate(evidence_items, 1):
                    print(f"    [{idx}] Document : {ev.get('document_name') or ev.get('document_id')}")
                    print(f"        Section  : {ev.get('section_title') or 'N/A'} (Page {ev.get('page_number')})")
                    print(f"        Match    : {int(ev.get('similarity_score', 0) * 100)}% similarity")
                    print(f"        Text     : \"{ev.get('clause_text')[:120]}...\"")
                    print(f"        Rationale: {ev.get('connection_rationale')}\n")
            else:
                print(f"[-] API error ({resp.status_code}): {resp.text}")
        except Exception as err:
            print(f"[-] Failed to connect evidence: {err}")

    print("=" * 70)
    print(" ML Evidence connection complete.")
    print("=" * 70)

if __name__ == "__main__":
    run_ml_pipeline()
